let appVariablesInstance;
let isInitialized = false;
const getAppVariablesInstance = (pageProxy, getAppVariables) => {
  if (!isInitialized) {
    appVariablesInstance = getAppVariables(pageProxy);
    isInitialized = true;
    console.log("App variables initialized once");
  }
  return appVariablesInstance;
};
const resetAppVariables = () => {
  appVariablesInstance = { Variables: {}, Actions: {} };
  isInitialized = false;
};
export {
  getAppVariablesInstance,
  resetAppVariables
};
